public class MasterSlaveRoutingDataSource extends AbstractRoutingDataSource {
    @Override
    protected Object determineCurrentLookupKey() {
        // TransactionSynchronizationManager determines if the current transaction is read-only
        return TransactionSynchronizationManager.isCurrentTransactionReadOnly() 
            ? TargetDataSource.SLAVE 
            : TargetDataSource.MASTER;
    }
}

// Configuration usage in Spring
@Configuration
public class DataSourceConfig {
    @Bean
    @Primary
    public DataSource dataSource(
            @Qualifier("masterDataSource") DataSource master,
            @Qualifier("slaveDataSource") DataSource slave) {
        Map<Object, Object> targetDataSources = new HashMap<>();
        targetDataSources.put(TargetDataSource.MASTER, master);
        targetDataSources.put(TargetDataSource.SLAVE, slave);

        MasterSlaveRoutingDataSource routingDataSource = new MasterSlaveRoutingDataSource();
        routingDataSource.setTargetDataSources(targetDataSources);
        routingDataSource.setDefaultTargetDataSource(master);
        return routingDataSource;
    }
}
